  1→import { useState, useEffect, useRef, useCallback } from 'react';
  2→import './Chessboard.css';
  3→import { INITIAL_BOARD, PIECE_TYPES } from './constants';
  4→import Piece from './Piece';
  5→import { playMoveSound, playCaptureSound, playNotifySound } from './sounds';
  6→import { isValidPawnMove, getEnPassantTarget, needsPromotion, indexToRowCol, isValidRookMove, isValidKnightMove, isValidBishopMove, isValidQueenMove, isValidKingMove, isKingInCheck, isCheckmate, isInsufficientMaterial, generatePositionKey } from './moveValidation';
  7→import ChessEngine from './chessEngine';
  8→
  9→function Chessboard({ initialState, onSave, onGameEnd, onBackToList, engineColorProp }) {
 10→  const s = initialState || {};
 11→
 12→  const [board, setBoard] = useState(() => s.board || INITIAL_BOARD);
 13→  const [draggedPiece, setDraggedPiece] = useState(null);
 14→  const [draggedFrom, setDraggedFrom] = useState(null);
 15→  const [enPassantTarget, setEnPassantTarget] = useState(() => s.enPassantTarget ?? null);
 16→  const [promotionSquare, setPromotionSquare] = useState(null);
 17→  const [movedPieces, setMovedPieces] = useState(() =>
 18→    s.movedPieces instanceof Set ? s.movedPieces : new Set(s.movedPieces || [])
 19→  );
 20→  const [currentTurn, setCurrentTurn] = useState(() => s.currentTurn || 'white');
 21→  const [halfMoveClock, setHalfMoveClock] = useState(() => s.halfMoveClock || 0);
 22→  const [positionHistory, setPositionHistory] = useState(() =>
 23→    s.positionHistory?.length ? s.positionHistory : [generatePositionKey(s.board || INITIAL_BOARD)]
 24→  );
 25→  const [validMoves, setValidMoves] = useState([]);
 26→  const [moveHistory, setMoveHistory] = useState(() => s.moveHistory || []);
 27→  const [isEngineThinking, setIsEngineThinking] = useState(false);
 28→
 29→  const engineColor = engineColorProp || s.engineColor || 'black';
 30→
 31→  const engineRef = useRef(null);
 32→  const lastMoveRef = useRef(null);
 33→  const gameEndedRef = useRef(s.result && s.result !== '*');
 34→  const saveCounterRef = useRef(0);
 35→  const rows = 8;
 36→  const cols = 8;
 37→
 38→  // Helper to record a move
 39→  const recordMove = useCallback((from, to, promotion) => {
 40→    const cols = 'abcdefgh';
 41→    const fromStr = cols[from % 8] + (8 - Math.floor(from / 8));
 42→    const toStr = cols[to % 8] + (8 - Math.floor(to / 8));
 43→    const promoStr = promotion ? { [PIECE_TYPES.QUEEN]: 'q', [PIECE_TYPES.ROOK]: 'r', [PIECE_TYPES.BISHOP]: 'b', [PIECE_TYPES.KNIGHT]: 'n' }[promotion] || '' : '';
 44→    setMoveHistory(prev => [...prev, fromStr + toStr + promoStr]);
 45→  }, []);
 46→
 47→  // Auto-save after every move
 48→  const triggerSave = useCallback((boardState, turnState, epTarget, movedSet, hmClock, posHistory, moves, result) => {
 49→    if (!onSave) return;
 50→    saveCounterRef.current += 1;
 51→    onSave({
 52→      board: boardState,
 53→      currentTurn: turnState,
 54→      enPassantTarget: epTarget,
 55→      movedPieces: [...movedSet],
 56→      halfMoveClock: hmClock,
 57→      positionHistory: posHistory,
 58→      moveHistory: moves,
 59→      result: result || '*',
 60→    });
 61→  }, [onSave]);
 62→
 63→  // Detect game result
 64→  const getGameResult = useCallback((boardState, hmClock, posHist) => {
 65→    const whiteInCheck = isKingInCheck(boardState, true);
 66→    const blackInCheck = isKingInCheck(boardState, false);
 67→    const whiteCheckmate = isCheckmate(boardState, true);
 68→    const blackCheckmate = isCheckmate(boardState, false);
 69→    const insuffMat = isInsufficientMaterial(boardState);
 70→    const fiftyMove = hmClock >= 100;
 71→    const pos = generatePositionKey(boardState);
 72→    const threefold = posHist.filter(p => p === pos).length >= 3;
 73→
 74→    if (whiteCheckmate && whiteInCheck) return '0-1';
 75→    if (blackCheckmate && blackInCheck) return '1-0';
 76→    if (insuffMat || fiftyMove || threefold) return '1/2-1/2';
 77→    if ((!whiteInCheck && whiteCheckmate) || (!blackInCheck && blackCheckmate)) return '1/2-1/2';
 78→    return null;
 79→  }, []);
 80→
 81→  // Initialize engine + auto-move if engine's turn on mount
 82→  useEffect(() => {
 83→    if (!engineRef.current) {
 84→      engineRef.current = new ChessEngine();
 85→      engineRef.current.init().then(() => {
 86→        // If resuming a game where it's the engine's turn, trigger engine move
 87→        const initBoard = s.board || INITIAL_BOARD;
 88→        const initTurn = s.currentTurn || 'white';
 89→        const initEngineColor = engineColorProp || s.engineColor || 'black';
 90→        const initResult = s.result || '*';
 91→        if (initTurn === initEngineColor && initResult === '*') {
 92→          setTimeout(() => makeEngineMove(initBoard, initTurn), 500);
 93→        }
 94→      });
 95→    }
 96→
 97→    return () => {
 98→      if (engineRef.current) {
 99→        engineRef.current.terminate();
100→        engineRef.current = null;
101→      }
102→    };
103→  }, []); // eslint-disable-line react-hooks/exhaustive-deps
104→
105→  // Play notification sound when game ends
106→  useEffect(() => {
107→    const result = getGameResult(board, halfMoveClock, positionHistory);
108→    if (result && !gameEndedRef.current) {
109→      gameEndedRef.current = true;
110→      playNotifySound();
111→      if (onGameEnd) onGameEnd(result);
112→    }
113→  }, [board, halfMoveClock, positionHistory, getGameResult, onGameEnd]);
114→
115→  const handleDragStart = (squareIndex, piece) => {
116→    setDraggedPiece(piece);
117→    setDraggedFrom(squareIndex);
118→
119→    const pieceType = Math.abs(piece);
120→    const isWhite = piece > 0;
121→    const moves = [];
122→
123→    for (let toIndex = 0; toIndex < 64; toIndex++) {
124→      if (toIndex === squareIndex) continue;
125→
126→      let isValid = false;
127→
128→      switch (pieceType) {
129→        case PIECE_TYPES.PAWN:
130→          isValid = isValidPawnMove(board, squareIndex, toIndex, enPassantTarget);
131→          break;
132→        case PIECE_TYPES.KNIGHT:
133→          isValid = isValidKnightMove(board, squareIndex, toIndex);
134→          break;
135→        case PIECE_TYPES.BISHOP:
136→          isValid = isValidBishopMove(board, squareIndex, toIndex);
137→          break;
138→        case PIECE_TYPES.ROOK:
139→          isValid = isValidRookMove(board, squareIndex, toIndex);
140→          break;
141→        case PIECE_TYPES.QUEEN:
142→          isValid = isValidQueenMove(board, squareIndex, toIndex);
143→          break;
144→        case PIECE_TYPES.KING: {
145→          const kingHasMoved = movedPieces.has(squareIndex);
146→          isValid = isValidKingMove(board, squareIndex, toIndex, kingHasMoved);
147→          break;
148→        }
149→      }
150→
151→      if (isValid) {
152→        const testBoard = [...board];
153→        testBoard[toIndex] = piece;
154→        testBoard[squareIndex] = 0;
155→
156→        if (pieceType === PIECE_TYPES.PAWN && toIndex === enPassantTarget) {
157→          const { row: toRow, col: toCol } = indexToRowCol(toIndex);
158→          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
159→          const capturedPawnIndex = capturedPawnRow * 8 + toCol;
160→          testBoard[capturedPawnIndex] = 0;
161→        }
162→
163→        if (!isKingInCheck(testBoard, isWhite)) {
164→          moves.push(toIndex);
165→        }
166→      }
167→    }
168→
169→    setValidMoves(moves);
170→  };
171→
172→  const handleDragOver = (e) => {
173→    e.preventDefault();
174→  };
175→
176→  const handlePromotion = (pieceType) => {
177→    if (promotionSquare === null) return;
178→
179→    const newBoard = [...board];
180→    const isWhite = board[promotionSquare] > 0;
181→    newBoard[promotionSquare] = isWhite ? pieceType : -pieceType;
182→
183→    setBoard(newBoard);
184→    setPromotionSquare(null);
185→
186→    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
187→    setCurrentTurn(nextTurn);
188→
189→    const positionKey = generatePositionKey(newBoard);
190→    const newPosHistory = [...positionHistory];
191→    newPosHistory[newPosHistory.length - 1] = positionKey;
192→    setPositionHistory(newPosHistory);
193→
194→    // Record the promotion move
195→    if (lastMoveRef.current) {
196→      recordMove(lastMoveRef.current.from, lastMoveRef.current.to, pieceType);
197→    }
198→    const newMoves = [...moveHistory];
199→    if (lastMoveRef.current) {
200→      const colChars = 'abcdefgh';
201→      const { from, to } = lastMoveRef.current;
202→      const promoChar = { [PIECE_TYPES.QUEEN]: 'q', [PIECE_TYPES.ROOK]: 'r', [PIECE_TYPES.BISHOP]: 'b', [PIECE_TYPES.KNIGHT]: 'n' }[pieceType] || '';
203→      newMoves.push(colChars[from % 8] + (8 - Math.floor(from / 8)) + colChars[to % 8] + (8 - Math.floor(to / 8)) + promoChar);
204→    }
205→
206→    lastMoveRef.current = null;
207→
208→    // Check for game end
209→    const result = getGameResult(newBoard, halfMoveClock, newPosHistory);
210→    triggerSave(newBoard, nextTurn, enPassantTarget, movedPieces, halfMoveClock, newPosHistory, newMoves, result);
211→
212→    if (nextTurn === engineColor && !result) {
213→      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
214→    }
215→  };
216→
217→  const handleDrop = (squareIndex) => {
218→    if (draggedFrom === null || draggedFrom === squareIndex) {
219→      setValidMoves([]);
220→      return;
221→    }
222→
223→    const pieceType = Math.abs(draggedPiece);
224→    const isWhite = draggedPiece > 0;
225→    const pieceColor = isWhite ? 'white' : 'black';
226→
227→    // Check if game is over
228→    if (gameEndedRef.current) {
229→      setDraggedPiece(null);
230→      setDraggedFrom(null);
231→      setValidMoves([]);
232→      return;
233→    }
234→
235→    const gameOver = isCheckmate(board, true) || isCheckmate(board, false) ||
236→                     isInsufficientMaterial(board) || halfMoveClock >= 100;
237→    const currentPos = generatePositionKey(board);
238→    const repCount = positionHistory.filter(pos => pos === currentPos).length;
239→    const gameOverRep = repCount >= 3;
240→
241→    if (gameOver || gameOverRep) {
242→      setDraggedPiece(null);
243→      setDraggedFrom(null);
244→      setValidMoves([]);
245→      return;
246→    }
247→
248→    if (pieceColor !== currentTurn) {
249→      setDraggedPiece(null);
250→      setDraggedFrom(null);
251→      setValidMoves([]);
252→      return;
253→    }
254→
255→    // Validate moves
256→    if (pieceType === PIECE_TYPES.PAWN && !isValidPawnMove(board, draggedFrom, squareIndex, enPassantTarget)) {
257→      setDraggedPiece(null); setDraggedFrom(null); setValidMoves([]); return;
258→    }
259→    if (pieceType === PIECE_TYPES.ROOK && !isValidRookMove(board, draggedFrom, squareIndex)) {
260→      setDraggedPiece(null); setDraggedFrom(null); setValidMoves([]); return;
261→    }
262→    if (pieceType === PIECE_TYPES.KNIGHT && !isValidKnightMove(board, draggedFrom, squareIndex)) {
263→      setDraggedPiece(null); setDraggedFrom(null); setValidMoves([]); return;
264→    }
265→    if (pieceType === PIECE_TYPES.BISHOP && !isValidBishopMove(board, draggedFrom, squareIndex)) {
266→      setDraggedPiece(null); setDraggedFrom(null); setValidMoves([]); return;
267→    }
268→    if (pieceType === PIECE_TYPES.QUEEN && !isValidQueenMove(board, draggedFrom, squareIndex)) {
269→      setDraggedPiece(null); setDraggedFrom(null); setValidMoves([]); return;
270→    }
271→    if (pieceType === PIECE_TYPES.KING) {
272→      const kingHasMoved = movedPieces.has(draggedFrom);
273→      if (!isValidKingMove(board, draggedFrom, squareIndex, kingHasMoved)) {
274→        setDraggedPiece(null); setDraggedFrom(null); setValidMoves([]); return;
275→      }
276→    }
277→
278→    // Check if move leaves king in check
279→    const testBoard = [...board];
280→    testBoard[squareIndex] = draggedPiece;
281→    testBoard[draggedFrom] = 0;
282→
283→    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
284→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
285→      const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
286→      testBoard[capturedPawnRow * 8 + toCol] = 0;
287→    }
288→
289→    if (isKingInCheck(testBoard, isWhite)) {
290→      setDraggedPiece(null);
291→      setDraggedFrom(null);
292→      return;
293→    }
294→
295→    // Execute the move
296→    let isCapture = board[squareIndex] !== 0;
297→    const newBoard = [...board];
298→    newBoard[squareIndex] = draggedPiece;
299→    newBoard[draggedFrom] = 0;
300→
301→    // Handle castling
302→    if (pieceType === PIECE_TYPES.KING) {
303→      const { row: fromRow, col: fromCol } = indexToRowCol(draggedFrom);
304→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
305→      if (Math.abs(toCol - fromCol) === 2) {
306→        const direction = toCol > fromCol ? 1 : -1;
307→        const rookCol = direction === 1 ? 7 : 0;
308→        const rookIndex = fromRow * 8 + rookCol;
309→        const newRookIndex = toRow * 8 + (toCol - direction);
310→        newBoard[newRookIndex] = newBoard[rookIndex];
311→        newBoard[rookIndex] = 0;
312→      }
313→    }
314→
315→    // Handle en passant capture
316→    if (pieceType === PIECE_TYPES.PAWN && squareIndex === enPassantTarget) {
317→      const { row: toRow, col: toCol } = indexToRowCol(squareIndex);
318→      const capturedPawnRow = draggedPiece > 0 ? toRow + 1 : toRow - 1;
319→      newBoard[capturedPawnRow * 8 + toCol] = 0;
320→      isCapture = true;
321→    }
322→
323→    const newEnPassantTarget = getEnPassantTarget(board, draggedFrom, squareIndex);
324→    setEnPassantTarget(newEnPassantTarget);
325→
326→    const isPromotion = needsPromotion(draggedPiece, squareIndex);
327→    if (isPromotion) {
328→      setPromotionSquare(squareIndex);
329→      lastMoveRef.current = { from: draggedFrom, to: squareIndex };
330→    }
331→
332→    setBoard(newBoard);
333→
334→    const newMovedPieces = new Set([...movedPieces, draggedFrom]);
335→    setMovedPieces(newMovedPieces);
336→
337→    const newHalfMoveClock = (pieceType === PIECE_TYPES.PAWN || isCapture) ? 0 : halfMoveClock + 1;
338→    setHalfMoveClock(newHalfMoveClock);
339→
340→    const positionKey = generatePositionKey(newBoard);
341→    const newPosHistory = [...positionHistory, positionKey];
342→    setPositionHistory(newPosHistory);
343→
344→    setDraggedPiece(null);
345→    setDraggedFrom(null);
346→    setValidMoves([]);
347→
348→    if (isCapture) { playCaptureSound(); } else { playMoveSound(); }
349→
350→    if (isPromotion) return;
351→
352→    // Record the move
353→    recordMove(draggedFrom, squareIndex);
354→    const newMoves = [...moveHistory];
355→    const colChars = 'abcdefgh';
356→    newMoves.push(colChars[draggedFrom % 8] + (8 - Math.floor(draggedFrom / 8)) + colChars[squareIndex % 8] + (8 - Math.floor(squareIndex / 8)));
357→
358→    const nextTurn = currentTurn === 'white' ? 'black' : 'white';
359→    setCurrentTurn(nextTurn);
360→
361→    // Check for game end and save
362→    const result = getGameResult(newBoard, newHalfMoveClock, newPosHistory);
363→    triggerSave(newBoard, nextTurn, newEnPassantTarget, newMovedPieces, newHalfMoveClock, newPosHistory, newMoves, result);
364→
365→    if (nextTurn === engineColor && !result) {
366→      setTimeout(() => makeEngineMove(newBoard, nextTurn), 500);
367→    }
368→  };
369→
370→  // Make engine move
371→  const makeEngineMove = async (currentBoard, turn) => {
372→    if (!engineRef.current || isEngineThinking) return;
373→
374→    setIsEngineThinking(true);
375→
376→    try {
377→      const castlingRights = 'KQkq';
378→
379→      const move = await engineRef.current.getBestMove(
380→        currentBoard,
381→        turn,
382→        halfMoveClock,
383→        castlingRights,
384→        enPassantTarget
385→      );
386→
387→      if (move) {
388→        const newBoard = [...currentBoard];
389→        const piece = newBoard[move.from];
390→        newBoard[move.to] = piece;
391→        newBoard[move.from] = 0;
392→
393→        const pieceType = Math.abs(piece);
394→
395→        // Handle castling
396→        if (pieceType === PIECE_TYPES.KING) {
397→          const { row: fromRow, col: fromCol } = indexToRowCol(move.from);
398→          const { row: toRow, col: toCol } = indexToRowCol(move.to);
399→          if (Math.abs(toCol - fromCol) === 2) {
400→            const direction = toCol > fromCol ? 1 : -1;
401→            const rookCol = direction === 1 ? 7 : 0;
402→            const rookIndex = fromRow * 8 + rookCol;
403→            const newRookIndex = toRow * 8 + (toCol - direction);
404→            newBoard[newRookIndex] = newBoard[rookIndex];
405→            newBoard[rookIndex] = 0;
406→          }
407→        }
408→
409→        // Handle en passant
410→        if (pieceType === PIECE_TYPES.PAWN && move.to === enPassantTarget) {
411→          const { row: toRow, col: toCol } = indexToRowCol(move.to);
412→          const isWhite = piece > 0;
413→          const capturedPawnRow = isWhite ? toRow + 1 : toRow - 1;
414→          newBoard[capturedPawnRow * 8 + toCol] = 0;
415→        }
416→
417→        const newEnPassantTarget = getEnPassantTarget(currentBoard, move.from, move.to);
418→        setEnPassantTarget(newEnPassantTarget);
419→
420→        // Handle promotion
421→        let promotionType = 0;
422→        if (move.promotion && needsPromotion(piece, move.to)) {
423→          const promotionMap = { q: PIECE_TYPES.QUEEN, r: PIECE_TYPES.ROOK, b: PIECE_TYPES.BISHOP, n: PIECE_TYPES.KNIGHT };
424→          const promotedPiece = piece > 0 ? promotionMap[move.promotion] : -promotionMap[move.promotion];
425→          newBoard[move.to] = promotedPiece;
426→          promotionType = promotionMap[move.promotion];
427→        }
428→
429→        setBoard(newBoard);
430→
431→        const newMovedPieces = new Set([...movedPieces, move.from]);
432→        setMovedPieces(newMovedPieces);
433→
434→        const isCapture = currentBoard[move.to] !== 0;
435→        const newHalfMoveClock = (pieceType === PIECE_TYPES.PAWN || isCapture) ? 0 : halfMoveClock + 1;
436→        setHalfMoveClock(newHalfMoveClock);
437→
438→        const positionKey = generatePositionKey(newBoard);
439→        const newPosHistory = [...positionHistory, positionKey];
440→        setPositionHistory(newPosHistory);
441→
442→        const nextTurn = turn === 'white' ? 'black' : 'white';
443→        setCurrentTurn(nextTurn);
444→
445→        if (isCapture) { playCaptureSound(); } else { playMoveSound(); }
446→
447→        // Record move
448→        recordMove(move.from, move.to, promotionType);
449→        const newMoves = [...moveHistory];
450→        const colChars = 'abcdefgh';
451→        const promoChar = move.promotion || '';
452→        newMoves.push(colChars[move.from % 8] + (8 - Math.floor(move.from / 8)) + colChars[move.to % 8] + (8 - Math.floor(move.to / 8)) + promoChar);
453→
454→        // Check for game end and save
455→        const result = getGameResult(newBoard, newHalfMoveClock, newPosHistory);
456→        triggerSave(newBoard, nextTurn, newEnPassantTarget, newMovedPieces, newHalfMoveClock, newPosHistory, newMoves, result);
457→      }
458→    } catch (error) {
459→      console.error('Engine error:', error);
460→    } finally {
461→      setIsEngineThinking(false);
462→    }
463→  };
464→
465→  const renderBoard = () => {
466→    const boardElements = [];
467→
468→    for (let y = 0; y < rows; y++) {
469→      const row = [];
470→
471→      for (let x = 0; x < cols; x++) {
472→        const squareIndex = y * 8 + x;
473→        const piece = board[squareIndex];
474→        const isLight = (x + y) % 2 === 0;
475→        const isValidMove = validMoves.includes(squareIndex);
476→        const squareClass = `square ${isLight ? 'light' : 'dark'}${isValidMove ? ' valid-move' : ''}`;
477→
478→        row.push(
479→          <div
480→            key={`${x}-${y}`}
481→            className={squareClass}
482→            onDragOver={handleDragOver}
483→            onDrop={() => handleDrop(squareIndex)}
484→          >
485→            {piece !== 0 && (
486→              <Piece
487→                type={piece}
488→                onDragStart={() => handleDragStart(squareIndex, piece)}
489→              />
490→            )}
491→          </div>
492→        );
493→      }
494→
495→      boardElements.push(
496→        <div key={y} className="row">
497→          {row}
498→        </div>
499→      );
500→    }
501→
502→    return boardElements;
503→  };
504→
505→  // Check game status for display
506→  const whiteInCheck = isKingInCheck(board, true);
507→  const blackInCheck = isKingInCheck(board, false);
508→  const whiteCheckmate = isCheckmate(board, true);
509→  const blackCheckmate = isCheckmate(board, false);
510→  const whiteStalemate = !whiteInCheck && whiteCheckmate;
511→  const blackStalemate = !blackInCheck && blackCheckmate;
512→  const fiftyMoveRule = halfMoveClock >= 100;
513→  const currentPosition = generatePositionKey(board);
514→  const positionCount = positionHistory.filter(pos => pos === currentPosition).length;
515→  const threefoldRepetition = positionCount >= 3;
516→  const insufficientMaterial = isInsufficientMaterial(board);
517→
518→  let gameStatus = '';
519→  let statusColor = '#ff6b6b';
520→
521→  if (whiteCheckmate && whiteInCheck) {
522→    gameStatus = 'Checkmate! Black wins!';
523→  } else if (blackCheckmate && blackInCheck) {
524→    gameStatus = 'Checkmate! White wins!';
525→  } else if (insufficientMaterial) {
526→    gameStatus = 'Draw - Insufficient material!';
527→    statusColor = '#4CAF50';
528→  } else if (fiftyMoveRule) {
529→    gameStatus = 'Draw - 50 move rule!';
530→    statusColor = '#4CAF50';
531→  } else if (threefoldRepetition) {
532→    gameStatus = 'Draw - Threefold repetition!';
533→    statusColor = '#4CAF50';
534→  } else if (whiteStalemate || blackStalemate) {
535→    gameStatus = 'Stalemate! Game is a draw!';
536→    statusColor = '#ffa500';
537→  } else if (whiteInCheck && currentTurn === 'white') {
538→    gameStatus = 'White is in check!';
539→  } else if (blackInCheck && currentTurn === 'black') {
540→    gameStatus = 'Black is in check!';
541→  }
542→
543→  return (
544→    <>
545→      <div className="game-controls">
546→        <div className="engine-settings">
547→          <button className="back-button" onClick={onBackToList}>Back to Games</button>
548→          {isEngineThinking && <span className="thinking">Engine thinking...</span>}
549→        </div>
550→      </div>
551→
552→      {gameStatus && (
553→        <div className="game-status" style={{ backgroundColor: statusColor }}>
554→          {gameStatus}
555→        </div>
556→      )}
557→
558→      <div className="chessboard">
559→        {renderBoard()}
560→      </div>
561→
562→      {promotionSquare !== null && (
563→        <div className="promotion-overlay">
564→          <div className="promotion-dialog">
565→            <h3>Promote Pawn</h3>
566→            <div className="promotion-choices">
567→              <button onClick={() => handlePromotion(PIECE_TYPES.QUEEN)}>
568→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.QUEEN : -PIECE_TYPES.QUEEN} />
569→                <span>Queen</span>
570→              </button>
571→              <button onClick={() => handlePromotion(PIECE_TYPES.ROOK)}>
572→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK} />
573→                <span>Rook</span>
574→              </button>
575→              <button onClick={() => handlePromotion(PIECE_TYPES.BISHOP)}>
576→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.BISHOP : -PIECE_TYPES.BISHOP} />
577→                <span>Bishop</span>
578→              </button>
579→              <button onClick={() => handlePromotion(PIECE_TYPES.KNIGHT)}>
580→                <Piece type={board[promotionSquare] > 0 ? PIECE_TYPES.KNIGHT : -PIECE_TYPES.KNIGHT} />
581→                <span>Knight</span>
582→              </button>
583→            </div>
584→          </div>
