 1→import { useState, useEffect, useCallback } from 'react';
 2→
 3→const SERVER_BASE = 'http://localhost:3001';
 4→const SS_TOKEN_KEY = 'server_auth_token';
 5→
 6→export function useServerAuth({ isAuthenticated, account, username }) {
 7→  const [serverToken, setServerToken] = useState(() => sessionStorage.getItem(SS_TOKEN_KEY));
 8→  const [isConnected, setIsConnected] = useState(() => !!sessionStorage.getItem(SS_TOKEN_KEY));
 9→
10→  // When passkey auth state changes, bridge to server token
11→  useEffect(() => {
12→    if (!isAuthenticated || !account || !username) {
13→      setServerToken(null);
14→      setIsConnected(false);
15→      sessionStorage.removeItem(SS_TOKEN_KEY);
16→      return;
17→    }
18→
19→    // If we already have a token in this session, skip
20→    const existing = sessionStorage.getItem(SS_TOKEN_KEY);
21→    if (existing) {
22→      setServerToken(existing);
23→      setIsConnected(true);
24→      return;
25→    }
26→
27→    let cancelled = false;
28→
29→    async function bridge() {
30→      try {
31→        const resp = await fetch(`${SERVER_BASE}/api/auth/token`, {
32→          method: 'POST',
33→          headers: { 'Content-Type': 'application/json' },
34→          body: JSON.stringify({ passkeyAddress: account, username }),
35→        });
36→
37→        if (!resp.ok) {
38→          console.error('Server auth bridge failed:', await resp.text());
39→          return;
40→        }
41→
42→        const data = await resp.json();
43→        if (!cancelled) {
44→          sessionStorage.setItem(SS_TOKEN_KEY, data.token);
45→          setServerToken(data.token);
46→          setIsConnected(true);
47→        }
48→      } catch (err) {
49→        console.error('Server auth bridge error:', err);
50→        if (!cancelled) {
51→          setIsConnected(false);
52→        }
53→      }
54→    }
55→
56→    bridge();
57→    return () => { cancelled = true; };
58→  }, [isAuthenticated, account, username]);
59→
60→  const logout = useCallback(() => {
61→    sessionStorage.removeItem(SS_TOKEN_KEY);
62→    setServerToken(null);
63→    setIsConnected(false);
64→  }, []);
65→
66→  return { serverToken, isConnected, logout };
67→}
