 46→      return;
 47→    }
 48→
 49→    // Check if this is a promotion move (use client-side check for UX dialog)
 50→    if (needsPromotion(draggedPiece, squareIndex)) {
 51→      setPromotionData({ from: draggedFrom, to: squareIndex, piece: draggedPiece });
 52→      setDraggedPiece(null);
 53→      setDraggedFrom(null);
 54→      setValidMoves([]);
 55→      return;
 56→    }
 57→
 58→    // Build UCI string
 59→    const cols = 'abcdefgh';
 60→    const fromStr = cols[draggedFrom % 8] + (8 - Math.floor(draggedFrom / 8));
 61→    const toStr = cols[squareIndex % 8] + (8 - Math.floor(squareIndex / 8));
 62→    const uci = fromStr + toStr;
 63→
 64→    // Play sound optimistically
 65→    const isCapture = game.board[squareIndex] !== 0;
 66→    if (isCapture) { playCaptureSound(); } else { playMoveSound(); }
 67→
 68→    setDraggedPiece(null);
 69→    setDraggedFrom(null);
 70→    setValidMoves([]);
 71→
 72→    await game.submitMove(uci);
 73→  }, [draggedFrom, draggedPiece, validMoves, game]);
 74→
 75→  const handlePromotion = useCallback(async (pieceType) => {
 76→    if (!promotionData) return;
 77→
 78→    const { from, to } = promotionData;
 79→    const cols = 'abcdefgh';
 80→    const fromStr = cols[from % 8] + (8 - Math.floor(from / 8));
 81→    const toStr = cols[to % 8] + (8 - Math.floor(to / 8));
 82→    const promoChar = { [PIECE_TYPES.QUEEN]: 'q', [PIECE_TYPES.ROOK]: 'r', [PIECE_TYPES.BISHOP]: 'b', [PIECE_TYPES.KNIGHT]: 'n' }[pieceType] || 'q';
 83→    const uci = fromStr + toStr + promoChar;
 84→
 85→    playCaptureSound();
 86→    setPromotionData(null);
 87→
 88→    await game.submitMove(uci);
 89→  }, [promotionData, game]);
 90→
 91→  // Loading state
 92→  if (game.status === 'loading' || !game.board) {
 93→    return (
 94→      <div className="online-loading">
 95→        <p>Loading game...</p>
 96→      </div>
 97→    );
 98→  }
 99→
100→  // Error state
101→  if (game.status === 'error') {
102→    return (
103→      <div className="online-error">
104→        <p>Error: {game.error}</p>
105→        <button className="back-button" onClick={onBackToList}>Back to Games</button>
106→      </div>
107→    );
108→  }
109→
110→  // Build game status message
111→  let gameStatus = '';
112→  let statusColor = '#ff6b6b';
113→
114→  const whiteInCheck = game.board ? isKingInCheck(game.board, true) : false;
115→  const blackInCheck = game.board ? isKingInCheck(game.board, false) : false;
116→
117→  if (game.gameResult) {
118→    playNotifySound();
119→    if (game.gameResult === '1-0') {
120→      gameStatus = 'Checkmate! White wins!';
121→    } else if (game.gameResult === '0-1') {
122→      gameStatus = 'Checkmate! Black wins!';
123→    } else {
124→      gameStatus = 'Draw!';
125→      statusColor = '#4CAF50';
126→    }
127→  } else if (whiteInCheck && game.currentTurn === 'white') {
128→    gameStatus = 'White is in check!';
129→  } else if (blackInCheck && game.currentTurn === 'black') {
130→    gameStatus = 'Black is in check!';
131→  } else if (!isMyTurn && game.status === 'playing') {
132→    gameStatus = "Opponent's turn...";
133→    statusColor = '#2196F3';
134→  }
135→
136→  // Determine promotion piece color for dialog
137→  const promoPieceIsWhite = promotionData ? promotionData.piece > 0 : true;
138→
139→  return (
140→    <>
141→      <div className="game-controls">
142→        <div className="engine-settings">
143→          <button className="back-button" onClick={onBackToList}>Back to Games</button>
144→          {game.room && (
145→            <span className="online-info">
146→              {game.room.white || '?'} vs {game.room.black || '?'}
147→              {game.room.isStockfish && ` (Stockfish Lv${game.room.stockfishLevel})`}
148→            </span>
149→          )}
150→        </div>
151→      </div>
152→
153→      {gameStatus && (
154→        <div className="game-status" style={{ backgroundColor: statusColor }}>
155→          {gameStatus}
156→        </div>
157→      )}
158→
159→      <div className="chessboard">
160→        {renderBoard(game.board, game.myColor, validMoves, handleDragStart, handleDragOver, handleDrop)}
161→      </div>
162→
163→      {promotionData && (
164→        <div className="promotion-overlay">
165→          <div className="promotion-dialog">
166→            <h3>Promote Pawn</h3>
167→            <div className="promotion-choices">
168→              <button onClick={() => handlePromotion(PIECE_TYPES.QUEEN)}>
169→                <Piece type={promoPieceIsWhite ? PIECE_TYPES.QUEEN : -PIECE_TYPES.QUEEN} />
170→                <span>Queen</span>
171→              </button>
172→              <button onClick={() => handlePromotion(PIECE_TYPES.ROOK)}>
173→                <Piece type={promoPieceIsWhite ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK} />
174→                <span>Rook</span>
175→              </button>
176→              <button onClick={() => handlePromotion(PIECE_TYPES.BISHOP)}>
177→                <Piece type={promoPieceIsWhite ? PIECE_TYPES.BISHOP : -PIECE_TYPES.BISHOP} />
178→                <span>Bishop</span>
179→              </button>
180→              <button onClick={() => handlePromotion(PIECE_TYPES.KNIGHT)}>
181→                <Piece type={promoPieceIsWhite ? PIECE_TYPES.KNIGHT : -PIECE_TYPES.KNIGHT} />
182→                <span>Knight</span>
183→              </button>
184→            </div>
185→          </div>
186→        </div>
187→      )}
188→    </>
189→  );
190→}
