192→function renderBoard(board, myColor, validMovesList, onDragStart, onDragOver, onDrop) {
193→  const boardElements = [];
194→  const rows = myColor === 'black' ? [7, 6, 5, 4, 3, 2, 1, 0] : [0, 1, 2, 3, 4, 5, 6, 7];
195→  const colOrder = myColor === 'black' ? [7, 6, 5, 4, 3, 2, 1, 0] : [0, 1, 2, 3, 4, 5, 6, 7];
196→
197→  for (const y of rows) {
198→    const row = [];
199→    for (const x of colOrder) {
200→      const squareIndex = y * 8 + x;
201→      const piece = board[squareIndex];
202→      const isLight = (x + y) % 2 === 0;
203→      const isValidMove = validMovesList.includes(squareIndex);
204→      const squareClass = `square ${isLight ? 'light' : 'dark'}${isValidMove ? ' valid-move' : ''}`;
205→
206→      row.push(
207→        <div
208→          key={`${x}-${y}`}
209→          className={squareClass}
210→          onDragOver={onDragOver}
211→          onDrop={() => onDrop(squareIndex)}
212→        >
213→          {piece !== 0 && (
214→            <Piece
215→              type={piece}
216→              onDragStart={() => onDragStart(squareIndex, piece)}
217→            />
218→          )}
219→        </div>
220→      );
221→    }
222→
223→    boardElements.push(
224→      <div key={y} className="row">
225→        {row}
226→      </div>
227→    );
228→  }
229→
230→  return boardElements;
231→}
