 21→function saveOnlineSession(view, roomId, inviteCode) {
 22→  if (view === 'online' || view === 'waiting') {
 23→    sessionStorage.setItem(SS_ONLINE_KEY, JSON.stringify({ view, roomId, inviteCode }));
 24→  } else {
 25→    sessionStorage.removeItem(SS_ONLINE_KEY);
 26→  }
 27→}
