 52→  const { publishGame: passkeyPublish } = usePasskeyPublish({
 53→    account: passkey.account,
 54→    credentialId: passkey.credentialId,
 55→    rawId: passkey.rawId,
 56→  });
 57→
 58→  // Persist online session to sessionStorage on state changes
 59→  useEffect(() => {
 60→    saveOnlineSession(view, onlineRoomId, onlineInviteCode);
 61→  }, [view, onlineRoomId, onlineInviteCode]);
 62→
 63→  // Scope game storage to the authenticated user
 64→  useEffect(() => {
 65→    if (passkey.isAuthenticated && passkey.account) {
 66→      setCurrentUser(passkey.account);
 67→    } else {
 68→      setCurrentUser(null);
