  1→const express = require('express');
  2→const cors = require('cors');
  3→const http = require('http');
  4→const rateLimit = require('express-rate-limit');
  5→const { createDb } = require('./db');
  6→const { authMiddleware } = require('./middleware/auth');
  7→const { createAuthRouter } = require('./routes/auth');
  8→const { createRoomsRouter } = require('./routes/rooms');
  9→const { setupWebSocket } = require('./ws');
 10→const { createStockfishPlayer } = require('./chess/stockfishPlayer');
 11→
 12→const PORT = process.env.PORT || 3001;
 13→
 14→async function main() {
 15→  // Initialize database
 16→  const db = createDb();
 17→
 18→  // Initialize Stockfish (awaited so engine is ready before accepting requests)
 19→  let stockfishPlayer = await createStockfishPlayer();
 20→
 21→  // Create Express app
 22→  const app = express();
 23→
 24→  // Middleware
 25→  app.use(express.json());
 26→  app.use(cors({
 27→    origin: [/^http:\/\/localhost:\d+$/, /^http:\/\/127\.0\.0\.1:\d+$/],
 28→    credentials: true
 29→  }));
 30→
 31→  // Request logging
 32→  app.use((req, res, next) => {
 33→    const start = Date.now();
 34→    res.on('finish', () => {
 35→      const duration = Date.now() - start;
 36→      console.log(`${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
 37→    });
 38→    next();
 39→  });
 40→
 41→  // Rate limiters
 42→  const isTest = process.env.NODE_ENV === 'test';
 43→
 44→  const signupLimiter = rateLimit({
 45→    windowMs: 60 * 1000, // 1 minute
 46→    max: 5,
 47→    standardHeaders: true,
 48→    legacyHeaders: false,
 49→    skip: () => isTest,
 50→    message: { error: 'Too many signup attempts. Try again in a minute.' }
 51→  });
 52→
 53→  const moveLimiter = rateLimit({
 54→    windowMs: 60 * 1000, // 1 minute
 55→    max: 60,
 56→    keyGenerator: (req) => req.user ? `user:${req.user.id}` : req.ip,
 57→    standardHeaders: true,
 58→    legacyHeaders: false,
 59→    skip: () => isTest,
 60→    message: { error: 'Too many moves. Slow down.' }
 61→  });
 62→
 63→  // Create HTTP server
 64→  const server = http.createServer(app);
 65→
 66→  // Setup WebSocket
 67→  const { broadcast } = setupWebSocket(server, db);
 68→
 69→  // Auth middleware instance
 70→  const auth = authMiddleware(db);
 71→
 72→  // Mount routes
 73→  app.use('/api/auth', signupLimiter, createAuthRouter(db));
 74→
 75→  const roomsRouter = createRoomsRouter(db, {
 76→    broadcast,
 77→    getStockfishPlayer: () => stockfishPlayer
 78→  });
 79→  app.use('/api/rooms', auth, roomsRouter);
 80→
 81→  // Apply move-specific rate limiter to move endpoint
 82→  app.use('/api/rooms/:id/move', moveLimiter);
 83→
 84→  // Health check
 85→  app.get('/api/health', (req, res) => {
 86→    res.json({
 87→      status: 'ok',
 88→      stockfish: !!stockfishPlayer
 89→    });
 90→  });
 91→
 92→  // Room expiry: every 5 minutes, delete stale waiting rooms
 93→  // Delete game_states first (child FK), then rooms (parent)
 94→  const findStaleRooms = db.prepare(`
 95→    SELECT id FROM rooms
 96→    WHERE status = 'waiting'
 97→    AND created_at < datetime('now', '-15 minutes')
 98→  `);
 99→  const deleteGameStateByRoom = db.prepare('DELETE FROM game_states WHERE room_id = ?');
100→  const deleteRoomById = db.prepare('DELETE FROM rooms WHERE id = ?');
101→
102→  const expireStaleRooms = db.transaction(() => {
103→    const stale = findStaleRooms.all();
104→    for (const row of stale) {
105→      deleteGameStateByRoom.run(row.id);
106→      deleteRoomById.run(row.id);
107→    }
108→    return stale.length;
109→  });
110→
111→  setInterval(() => {
112→    const count = expireStaleRooms();
113→    if (count > 0) {
114→      console.log(`Expired ${count} stale waiting room(s)`);
115→    }
116→  }, 5 * 60 * 1000);
117→
118→  // Start server
119→  server.listen(PORT, () => {
120→    console.log(`Chess server listening on http://localhost:${PORT}`);
121→    console.log(`WebSocket available at ws://localhost:${PORT}/api/rooms/:id/ws?token=xxx`);
122→  });
123→
124→  // Graceful shutdown
125→  process.on('SIGINT', () => {
126→    console.log('\nShutting down...');
127→    if (stockfishPlayer) stockfishPlayer.terminate();
128→    db.close();
129→    server.close();
130→    process.exit(0);
131→  });
132→}
133→
134→main().catch(err => {
135→  console.error('Failed to start server:', err);
136→  process.exit(1);
137→});
